<!DOCTYPE html> <html> <head> <title>Load All Data at Once</title> <!-- ✅ Ag-Grid Legacy Theme (v33 compatibility) --> 
<link href="https://cdn.jsdelivr.net/npm/ag-grid-community/styles/ag-grid.css" rel="stylesheet">
<link href="https://cdn.jsdelivr.net/npm/ag-grid-community/styles/ag-theme-alpine.css" rel="stylesheet"> <!-- ✅ Ag-Grid JS --> <script src="https://cdn.jsdelivr.net/npm/ag-grid-community/dist/ag-grid-community.min.js"></script> <!-- ✅ jsPDF + autoTable for PDF Export --> <script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script> <script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.5.25/jspdf.plugin.autotable.min.js"></script> <style> #buttons { margin: 10px; } #buttons button { margin-right: 10px; } </style> </head> <body> <!-- 🔘 Export Buttons --> <div id="buttons"> <button onclick="exportToExcel()">Export to Excel</button> <button onclick="exportToPDF()">Export to PDF</button> </div> <!-- 📊 Grid Container --> <div id="myGrid" class="ag-theme-alpine" style="height: 600px; width: 100%;"></div> 

<script> const columnDefs = [ { headerName: "Job Name", field: "name", sortable: true, filter: true }, { headerName: "User ID", field: "id", sortable: true, filter: true }, { headerName: "Description", field: "cost", sortable: true, filter: true } ]; let gridApi;
// 🟢 Store globally
const gridOptions = { columnDefs: columnDefs, defaultColDef: { resizable: true, flex: 1, minWidth: 120, sortable: true, filter: true }, pagination: true, paginationPageSize: 100, animateRows: true, theme: 'legacy', onGridReady: function(params) { gridApi = params.api; // ✅ Save the API 
} }; document.addEventListener('DOMContentLoaded', function () { const gridDiv = document.querySelector('#myGrid'); fetch("<?= base_url('brand/fetch_all_records') ?>") .then(response => response.json()) .then(data => { gridOptions.rowData = data.rows; agGrid.createGrid(gridDiv, gridOptions); }) .catch(error => console.error("Error loading data:", error)); }); function exportToExcel() { if (gridApi) { gridApi.exportDataAsExcel(); } else { alert("Grid not ready yet."); } } async function exportToPDF() { const { jsPDF } = window.jspdf; const doc = new jsPDF(); const rowData = []; if (!gridApi) { alert("Grid not ready yet."); return; } gridApi.forEachNodeAfterFilterAndSort(function (node) { rowData.push(node.data); }); const headers = columnDefs.map(col => col.headerName); const data = rowData.map(row => columnDefs.map(col => row[col.field])); doc.text("Job Data", 14, 15); doc.autoTable({ head: [headers], body: data, startY: 20 }); doc.save("job_data.pdf"); } </script> </body> </html>